    const overdue = crmTasks.filter(t => !t.done && t.dueAt && t.dueAt * 1000 < Date.now());
    const soon = crmTasks.filter(t => !t.done).slice(0, 6);

    // Воронка: сколько сделок стоит на каждой стадии. Показывает, где
