            <div class="merged-stat"><b>${formatMoney(crmMeta.pipelineValue)}</b><span>в пайплайне</span></div>
            <div class="merged-stat"><b class="ok">${formatMoney(crmMeta.wonValue)}</b><span>выиграно</span></div>
