content.content:
.app-shell__navpane {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--space-7);
  min-height: 0;
  padding: var(--space-6) var(--space-5);
  background: var(--material-chrome);
  backdrop-filter: var(--blur-lg);
  -webkit-backdrop-filter: var(--blur-lg);
  border-right: 1px solid var(--border);
  overflow-y: auto;
}

.app-shell__brand {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  padding: 0 var(--space-2);
  flex-shrink: 0;
}

.app-shell__mark {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  border-radius: var(--radius-md);
  background: var(--white);
  color: var(--text-on-accent);
  font-size: var(--text-xs);
  font-weight: var(--weight-bold);
  letter-spacing: 0.02em;
  box-shadow: var(--shadow-md);
}

.app-shell__title {
  margin: 0;
  font-size: var(--text-md);
  font-weight: var(--weight-semibold);
  letter-spacing: var(--tracking-tight);
  color: var(--text);
}

/* Кнопка закрытия нужна только выдвижной панели на мобильном. */
.app-shell__nav-close {
  display: none;
  margin-left: auto;
}

.app-shell__tagline {
  margin: 0;
  font-size: var(--text-xs);
  color: var(--text-tertiary);
}

/* --- Навигация с переезжающим выделением ---------------------------------------
   Подложка активного пункта — отдельный слой под ссылками. Она переезжает
   между пунктами, а не гаснет и зажигается: взгляд отслеживает движение
   и не теряет, где он оказался. */

.app-shell__nav {
  position: relative;
  display: grid;
  gap: 2px;
}

.app-shell__nav-indicator {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  border-radius: var(--radius-md);
  background: var(--control-hover);
  box-shadow: var(--hairline-top);
  pointer-events: none;
  opacity: 0;
  transition:
    transform var(--duration-slow) var(--ease-spring),
    height var(--duration-slow) var(--ease-out),
    opacity var(--duration-fast) var(--ease-out);
}

.app-shell__nav-indicator--ready {
  opacity: 1;
}

/* Первое появление не должно проезжать через весь список. */
.app-shell__nav-indicator--instant {
  transition: opacity var(--duration-fast) var(--ease-out);
}

.app-shell__nav-link {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: var(--space-4);
  min-height: 36px;
  padding: 0 var(--space-4);
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  text-decoration: none;
  font-size: var(--text-base);
  font-weight: var(--weight-medium);
  transition:
    transform var(--duration-fast) var(--ease-out),
    background-color var(--duration-fast) var(--ease-out),
    color var(--duration-base) var(--ease-out);
}

.app-shell__nav-link:active {
  transform: scale(0.97);
  transition-duration: var(--duration-instant);
}

.app-shell__nav-link--active {
  color: var(--text);
}

