old = """    /* Рельс меню темнее холста, а не светлее, как было (#1c1c1e поверх
       чёрного): панель навигации должна уходить назад, а не выступать
       вперёд контента. Холст чуть приподнят, чтобы граница читалась без
       яркого разделителя. */
    --bg-canvas: #0d0d0f;
    --bg-rail: #060607;
    --bg-rail-hover: rgba(255, 255, 255, 0.045);
    --bg-rail-active: rgba(255, 255, 255, 0.075);"""
new = """    /* Рельс меню по материальной модели InSights (см. DESIGN.md и
       tokens.css в apps/web): интерфейс - стопка слоёв над фоновой средой,
       и глубина берётся из того, что слой пропускает сквозь себя нижние.
       Хром при этом ПРИТЕМНЯЕТ подложку, а не поднимает её: панель должна
