.nav-indicator.ready { opacity: 1; }
/* Первое появление не должно проезжать через весь список. */
.nav-indicator.instant { transition: opacity 140ms var(--ease-out); }

.view {
    position: absolute; top: 0; left: 0; right: 0; bottom: 0; overflow-y: auto; overflow-x: hidden;
    background-color: var(--bg-canvas); display: none; opacity: 0; transition: opacity 0.2s ease; padding-bottom: 40px;
}
.view.active { display: block; opacity: 1; }

.large-header {
    padding: 28px 24px 16px 24px; position: sticky; top: 0; background: color-mix(in srgb, var(--bg-canvas) 88%, transparent);
    backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); z-index: 10; border-bottom: 0.5px solid var(--separator);
}
.large-header p { margin: 0 0 2px 0; font-size: 11px; color: var(--text-secondary); text-transform: uppercase; font-weight: 600; letter-spacing: 0.5px; }
.large-header h1 { margin: 0; font-size: 28px; font-weight: 700; letter-spacing: -0.5px; }

/* KANBAN BOARD */
.kanban-board { display: flex; gap: 16px; padding: 24px; overflow-x: auto; height: calc(100vh - 120px); }
.kanban-column { flex: 1; min-width: 250px; background: var(--bg-grouped); border-radius: 16px; padding: 16px; display: flex; flex-direction: column; border: 1px solid rgba(255,255,255,0.05); }
.kanban-column-header { display: flex; justify-content: space-between; font-weight: 700; font-size: 15px; margin-bottom: 14px; padding-bottom: 8px; border-bottom: 0.5px solid var(--separator); }
.kanban-count { background: rgba(255,255,255,0.1); padding: 2px 8px; border-radius: 10px; font-size: 12px; }
.kanban-cards { flex: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 10px; }
.kanban-card { background: rgba(255,255,255,0.04); border-radius: 12px; padding: 12px; border: 1px solid rgba(255,255,255,0.08); cursor: grab; transition: transform 0.15s; }
.kanban-card:active { cursor: grabbing; transform: scale(0.98); }

/* DASHBOARD & ANALYTICS */
.analytics-container { padding: 24px; max-width: 900px; margin: 0 auto; display: flex; flex-direction: column; gap: 20px; }
.analytics-card { background: var(--bg-grouped); border-radius: 16px; padding: 20px; border: 1px solid rgba(255,255,255,0.08); }
.progress-bar-bg { width: 100%; height: 8px; background: rgba(255,255,255,0.1); border-radius: 4px; overflow: hidden; }
.progress-bar-fill { height: 100%; border-radius: 4px; transition: width 0.3s ease; }
.stat-box { background: rgba(255,255,255,0.03); border-radius: 12px; padding: 14px; text-align: center; border: 1px solid rgba(255,255,255,0.05); }

/* BADGES & LIMITS */
.funnel-badge { font-size: 10px; font-weight: 700; padding: 3px 6px; border-radius: 5px; text-transform: uppercase; margin-right: 4px; }
.limit-badge { font-size: 11px; font-weight: 600; padding: 4px 8px; border-radius: 6px; border: 1px solid var(--accent-green); color: var(--accent-green); display: inline-block; margin-bottom: 12px; }
.warning-banner { background: rgba(255, 159, 10, 0.15); border: 1px solid var(--accent-orange); color: var(--accent-orange); padding: 12px; border-radius: 12px; font-size: 13px; margin-bottom: 16px; }

.products-grid { padding: 24px; display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 16px; }
.product-card { background: var(--bg-grouped); border-radius: 16px; padding: 20px; cursor: pointer; transition: transform 0.15s ease, background 0.2s; border: 1px solid rgba(255, 255, 255, 0.06); display: flex; flex-direction: column; justify-content: space-between; }
=== счётчик использований ===
schedule-btn   25
tg-btn         0
edit-btn       58
delete-btn     10
submit-btn     21
back-btn       7
group-chip     8

