import io
p='styles.css'
s=io.open(p,encoding='utf-8').read()

# --- поверхности: стекло вместо непрозрачных плашек ---------------------
old = """    --bg-canvas: #0d0d0f;
    --rail-env: #050506;
    --material-chrome: rgba(0, 0, 0, 0.55);"""
new = """    --bg-canvas: #08080a;
    --rail-env: #050506;
    --material-chrome: rgba(0, 0, 0, 0.55);
    /* Контентные слои, наоборот, ПОДНИМАЮТ подложку белым с малой альфой -
       так карточка читается как лист над средой, а не как серый
       прямоугольник. Непрозрачный вариант нужен там, где стекло поверх
       стекла превратилось бы в кашу: перетаскиваемая карточка, выпадашки. */
    --surface: rgba(255, 255, 255, 0.04);
    --surface-raised: rgba(255, 255, 255, 0.065);
    --surface-sunken: rgba(0, 0, 0, 0.28);
    --surface-solid: #17171a;
    --border-subtle: rgba(255, 255, 255, 0.055);
    --border-strong: rgba(255, 255, 255, 0.16);
    --danger-surface: rgba(255, 69, 58, 0.14);
    --danger-border: rgba(255, 69, 58, 0.3);
    --rose-300: #ff8f88;"""
assert s.count(old)==1
s=s.replace(old,new)

old2 = """    --bg-grouped: #1c1c1e;
    --bg-grouped-active: #2c2c2e;"""
new2 = """    --bg-grouped: var(--surface);
    --bg-grouped-active: var(--surface-raised);"""
assert s.count(old2)==1
s=s.replace(old2,new2)

# --- фоновая среда -------------------------------------------------------
old3 = """html, body {
    margin: 0; padding: 0;
    background-color: var(--bg-base);"""
new3 = """html, body {
    margin: 0; padding: 0;
    background-color: var(--bg-canvas);"""
assert s.count(old3)==1
s=s.replace(old3,new3)

anchor = ".app-container { width: 100%; height: 100vh;"
ambient = """/* Фоновая среда: несколько очень бледных пятен под всем интерфейсом. Нужна
   не ради красоты как таковой - без неё полупрозрачные карточки выглядят
   просто светло-серыми прямоугольниками на плоской заливке. Сквозь среду те
   же слои читаются как стекло разной плотности. Слой неподвижен
   (position: fixed), поэтому не участвует в скролле и ничего не перерисовывает
   при прокрутке длинных списков. */
body:before {
    content: ''; position: fixed; inset: -20%; z-index: 0; pointer-events: none;
    background:
        radial-gradient(40rem 34rem at 46% 2%, rgba(255, 255, 255, 0.075), transparent 66%),
        radial-gradient(34rem 30rem at 76% 52%, rgba(255, 255, 255, 0.05), transparent 64%),
        radial-gradient(46rem 38rem at 22% 96%, rgba(255, 255, 255, 0.045), transparent 68%);
    will-change: transform;
}
/* Пятна очень медленно дышат: период выбран так, чтобы движение нельзя было
   заметить намеренно - только почувствовать. Анимируется только transform. */
@keyframes ambient-drift {
    from { transform: translate3d(0, 0, 0) scale(1); }
    to { transform: translate3d(2%, -1.5%, 0) scale(1.06); }
}
@media (prefers-reduced-motion: no-preference) {
    body:before { animation: ambient-drift 72s var(--ease-in-out) infinite alternate; }
}

"""
assert s.count(anchor)==1
s=s.replace(anchor, ambient+anchor)

# Контейнер и вьюхи становятся прозрачными - иначе среда под ними не видна.
s=s.replace(
"    .view-container { flex: 1; height: 100%; position: relative; background: var(--bg-canvas); }",
"    .view-container { flex: 1; height: 100%; position: relative; }")
s=s.replace(
"    .view-container { position: absolute; top: 0; left: 0; right: 0; bottom: var(--tab-bar-height); background: var(--bg-canvas); }",
"    .view-container { position: absolute; top: 0; left: 0; right: 0; bottom: var(--tab-bar-height); }")
old4 = "    background-color: var(--bg-canvas); display: none; opacity: 0; transition: opacity 0.2s ease; padding-bottom: 40px;"
new4 = "    background-color: transparent; display: none; opacity: 0; transition: opacity 0.2s ease; padding-bottom: 40px;"
assert s.count(old4)==1
s=s.replace(old4,new4)

# Липкая шапка должна прятать уезжающий под неё контент - значит непрозрачнее
# среды, но с размытием, чтобы пятна за ней не обрывались резко.
old5 = ".large-header {\n    padding: 28px 24px 16px 24px; position: sticky; top: 0; background: color-mix(in srgb, var(--bg-canvas) 88%, transparent);\n    backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); z-index: 10; border-bottom: 0.5px solid var(--separator);"
new5 = ".large-header {\n    padding: 28px 24px 16px 24px; position: sticky; top: 0; background: rgba(8, 8, 10, 0.72);\n    backdrop-filter: blur(24px) saturate(160%); -webkit-backdrop-filter: blur(24px) saturate(160%); z-index: 10;\n    border-bottom: 1px solid var(--border-subtle);"
assert s.count(old5)==1
s=s.replace(old5,new5)
io.open(p,'w',encoding='utf-8').write(s)
print('ok')
