.delete-btn { background: rgba(255, 69, 58, 0.15); color: var(--accent-red); border: none; border-radius: 10px; padding: 8px 12px; font-size: 12px; font-weight: 600; cursor: pointer; }"""

new = """.action-btn-row { display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap; }

/* ЕДИНАЯ МЕХАНИКА КНОПОК
   Раньше каждый класс задавал свои отступы и вес, а варианты различались
   только цветом заливки: рядом стояли кнопки разной высоты, и ни одна не
   реагировала на нажатие. Общая часть теперь одна, различаются только три
   переменные - фон, текст, рамка. Отсюда одинаковая высота в любом ряду,
   одинаковый отклик и предсказуемое disabled-состояние.
   Второстепенные кнопки подсвечены волосяной линией по верхнему краю: так
   читается толщина стеклянного слоя, и это дешевле честной рамки. */
.schedule-btn, .tg-btn, .edit-btn, .delete-btn, .submit-btn,
.cc-primary, .cc-secondary {
    --btn-bg: transparent;
    --btn-fg: var(--text-primary);
    --btn-border: transparent;
    position: relative;
    display: inline-flex; align-items: center; justify-content: center; gap: 6px;
    min-height: 36px; padding: 0 14px;
    border: 1px solid var(--btn-border); border-radius: 11px;
    background: var(--btn-bg); color: var(--btn-fg);
    font-family: inherit; font-size: 13px; font-weight: 600; line-height: 1;
    white-space: nowrap; cursor: pointer;
    transition: transform 140ms var(--ease-out), background-color 140ms var(--ease-out),
                border-color 140ms var(--ease-out), color 140ms var(--ease-out), opacity 140ms var(--ease-out);
}
.schedule-btn:not(:disabled):active, .tg-btn:not(:disabled):active,
.edit-btn:not(:disabled):active, .delete-btn:not(:disabled):active,
.submit-btn:not(:disabled):active, .cc-primary:not(:disabled):active,
.cc-secondary:not(:disabled):active { transform: scale(0.97); transition-duration: 100ms; }

.schedule-btn:disabled, .tg-btn:disabled, .edit-btn:disabled, .delete-btn:disabled,
.submit-btn:disabled, .cc-primary:disabled, .cc-secondary:disabled, .cc-link:disabled {
    opacity: 0.35; cursor: not-allowed; transform: none;
}
.schedule-btn:focus-visible, .tg-btn:focus-visible, .edit-btn:focus-visible,
.delete-btn:focus-visible, .submit-btn:focus-visible,
.cc-primary:focus-visible, .cc-secondary:focus-visible {
    outline: none; box-shadow: 0 0 0 2px var(--bg-canvas), 0 0 0 4px rgba(10, 132, 255, 0.7);
}

/* Главное действие - единственная сплошная плоскость в ряду. */
.schedule-btn, .tg-btn, .submit-btn, .cc-primary {
    --btn-bg: var(--accent-blue); --btn-fg: #fff; --btn-border: transparent;
    box-shadow: 0 2px 10px rgba(10, 132, 255, 0.22);
}
.edit-btn, .cc-secondary {
    --btn-bg: var(--control); --btn-fg: var(--text-primary); --btn-border: var(--border-subtle);
