}
.delete-btn, .cc-danger {
    --btn-bg: var(--danger-surface); --btn-fg: var(--rose-300); --btn-border: var(--danger-border);
    box-shadow: none;
}

@media (hover: hover) and (pointer: fine) {
    .schedule-btn:not(:disabled):hover, .tg-btn:not(:disabled):hover,
    .submit-btn:not(:disabled):hover, .cc-primary:not(:disabled):hover { --btn-bg: #2b96ff; }
    .edit-btn:not(:disabled):hover, .cc-secondary:not(:disabled):hover {
