cat > /private/tmp/claude-501/-Users-kiruxa-Desktop-alba-content-hub/84af299b-0884-4ad6-8f4a-9413895cd35f/scratchpad/ui-btn.css <<'CSSEOF'
/* ==========================================================================
   ПРИМИТИВ: КНОПКА (.ui-btn)
   Один элемент на всё приложение. До этого кнопок было десять классов -
   schedule-btn, edit-btn, submit-btn, delete-btn, cc-primary, cc-secondary,
   back-btn и далее, - каждый со своей высотой, шрифтом и поведением; общие
   правила приходилось склеивать длинными списками селекторов, и любая
   правка требовала не забыть все десять. Теперь общая механика одна,
   вариант задаётся модификатором и меняет только три переменные.
   ========================================================================== */
.ui-btn {
    --btn-bg: transparent;
    --btn-fg: var(--text-primary);
    --btn-border: transparent;

    position: relative;
    display: inline-flex; align-items: center; justify-content: center; gap: 6px;
    min-height: var(--control-h); padding: 0 14px;
    border: 1px solid var(--btn-border); border-radius: 11px;
    background: var(--btn-bg); color: var(--btn-fg);
    font-family: inherit; font-size: 13px; font-weight: 600; line-height: 1;
    white-space: nowrap; cursor: pointer; text-decoration: none;
    transition: transform 140ms var(--ease-out), background-color 140ms var(--ease-out),
                border-color 140ms var(--ease-out), color 140ms var(--ease-out),
                box-shadow 140ms var(--ease-out), filter 140ms var(--ease-out),
                opacity 140ms var(--ease-out);
}
.ui-btn:not(:disabled):active { transform: scale(0.97); transition-duration: 100ms; }
.ui-btn:disabled, .ui-btn[aria-disabled="true"] { opacity: 0.35; cursor: not-allowed; transform: none; }
.ui-btn:focus-visible {
    outline: none;
    box-shadow: 0 0 0 2px var(--bg-canvas), 0 0 0 4px rgba(255, 255, 255, 0.85);
}

/* Главное действие - единственная сплошная белая плоскость в ряду. Цветом
   здесь ничего не выделяется: рядом со стеклянными кнопками белая читается
   мгновенно, а синий в интерфейсе уже занят ссылками и числами.
   Клавиша собрана из слоёв: едва заметный градиент даёт выпуклость, светлая
   кромка по верху и тёмная по низу - толщину, широкая мягкая тень со
   смещением сажает её над поверхностью, узкая держит контакт. */
.ui-btn--primary {
    --btn-bg: linear-gradient(180deg, #ffffff 0%, #e9e9ee 100%);
    --btn-fg: var(--text-on-accent);
    --btn-border: transparent;
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.9),
        inset 0 -1px 0 rgba(0, 0, 0, 0.08),
        0 6px 18px -6px rgba(0, 0, 0, 0.65),
        0 1px 2px rgba(0, 0, 0, 0.45);
    letter-spacing: -0.01em;
}
.ui-btn--secondary {
    --btn-bg: var(--control); --btn-fg: var(--text-primary); --btn-border: var(--border-subtle);
    box-shadow: var(--hairline-top);
}
.ui-btn--danger {
    --btn-bg: var(--danger-surface); --btn-fg: var(--rose-300); --btn-border: var(--danger-border);
}
.ui-btn--ghost { --btn-fg: var(--text-secondary); }
.ui-btn--link {
    --btn-fg: var(--accent-blue);
    min-height: 0; padding: 0; border: none; background: none;
    font-size: 12px; border-radius: 6px;
}
.ui-btn--link:not(:disabled):active { transform: none; }

/* Выбранное состояние переключателя (площадка публикации, язык). Красить
   выбор заливкой главной кнопки нельзя: это уравняло бы «я выбрал Telegram»
   и «отправить пост». */
.ui-btn.on {
    --btn-bg: var(--control-hover); --btn-fg: rgba(255, 255, 255, 0.96); --btn-border: var(--border-strong);
}

@media (hover: hover) and (pointer: fine) {
    /* Наведение на главную - подъём: осветлять белое некуда, работает
       только глубина. */
    .ui-btn--primary:not(:disabled):hover {
        transform: translateY(-1px);
        box-shadow:
            inset 0 1px 0 rgba(255, 255, 255, 0.95),
            inset 0 -1px 0 rgba(0, 0, 0, 0.08),
            0 10px 26px -8px rgba(0, 0, 0, 0.7),
            0 2px 4px rgba(0, 0, 0, 0.45);
    }
    .ui-btn--secondary:not(:disabled):hover {
        --btn-bg: var(--control-hover); --btn-border: var(--border-strong);
    }
    .ui-btn--danger:not(:disabled):hover {
        --btn-bg: rgba(255, 69, 58, 0.22); --btn-border: var(--accent-red);
    }
    .ui-btn--ghost:not(:disabled):hover { --btn-bg: var(--control); --btn-fg: var(--text-primary); }
    .ui-btn--link:not(:disabled):hover { --btn-fg: #4aa8ff; }
}

/* Нажатие главной вдавливает клавишу: тень схлопывается внутрь, свет по
   верхней кромке гаснет. Одного scale мало - он читается как
   «уменьшилось», а не «нажалось». */
.ui-btn--primary:not(:disabled):active {
    transform: translateY(1px) scale(0.985);
    filter: brightness(0.94);
    box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.18), 0 1px 2px rgba(0, 0, 0, 0.4);
}

/* Размеры и форма */
.ui-btn--sm { min-height: 32px; padding: 0 11px; font-size: 12px; border-radius: 9px; }
.ui-btn--lg { min-height: 46px; padding: 0 18px; font-size: 15px; border-radius: 12px; }
.ui-btn--block { width: 100%; }
.ui-btn--icon { width: var(--control-h); padding: 0; flex-shrink: 0; }
.ui-btn--icon.ui-btn--sm { width: 32px; }
