import io
p='styles.css'
s=io.open(p,encoding='utf-8').read()

# --- ПРИМИТИВЫ: БЕЙДЖ, ПОВЕРХНОСТЬ, ПУСТОЕ СОСТОЯНИЕ --------------------
anchor = "/* ==========================================================================\n   ПРИМИТИВ: КНОПКА (.ui-btn)"
prims = '''/* ==========================================================================
   ПРИМИТИВ: БЕЙДЖ (.ui-badge)
   Восемь классов делали одно и то же - пилюля с текстом: cc-pill,
   format-tag, funnel-badge, card-badge, limit-badge, kanban-count,
   crm-obj-count, parser-niche-status. Отличались только оттенком и парой
   пикселей отступа. Форма теперь одна, цвет задаётся тоном.
   ========================================================================== */
.ui-badge {
    --badge-bg: rgba(255, 255, 255, 0.08);
    --badge-fg: var(--text-secondary);
    display: inline-flex; align-items: center; gap: 4px;
    padding: 3px 9px; border-radius: 7px;
    background: var(--badge-bg); color: var(--badge-fg);
    font-size: 11px; font-weight: 600; line-height: 1.45; white-space: nowrap;
}
.ui-badge--blue   { --badge-bg: rgba(10, 132, 255, 0.15);  --badge-fg: var(--accent-blue); }
.ui-badge--green  { --badge-bg: rgba(48, 209, 88, 0.15);   --badge-fg: var(--accent-green); }
.ui-badge--orange { --badge-bg: rgba(255, 159, 10, 0.15);  --badge-fg: var(--accent-orange); }
.ui-badge--red    { --badge-bg: rgba(255, 69, 58, 0.15);   --badge-fg: var(--accent-red); }
.ui-badge--purple { --badge-bg: rgba(191, 90, 242, 0.15);  --badge-fg: var(--accent-purple); }
/* Заглавные - для статусов, где важно опознать состояние с одного взгляда,
   а не прочитать слово. */
.ui-badge--caps { text-transform: uppercase; letter-spacing: 0.3px; font-weight: 700; }
.ui-badge--outline { background: transparent; border: 1px solid currentColor; }

/* ==========================================================================
   ПРИМИТИВ: ПОВЕРХНОСТЬ (.ui-card)
   Девять классов повторяли один и тот же материал - стекло, рамка,
   скругление, волосяная линия: idea-card, cc-card, crm-panel,
   analytics-card, product-card, info-box, stat-box, parser-niche-card,
   merged-stat. Примитив даёт только материал; раскладку (отступы, flex,
   grid) по-прежнему задаёт класс конкретного места - иначе пришлось бы
   тащить в примитив девять разных раскладок.
   ========================================================================== */
.ui-card {
    background: var(--surface);
    border: 1px solid var(--border-subtle);
    border-radius: 14px;
    box-shadow: var(--hairline-top);
}
.ui-card--raised { background: var(--surface-raised); }
.ui-card--sunken { background: var(--surface-sunken); box-shadow: none; }
.ui-card--flat { box-shadow: none; }
.ui-card--pad { padding: 16px; }
.ui-card--pad-lg { padding: 20px; }
/* Кликабельная карточка: подъём при наведении вместо смены цвета. */
.ui-card--interactive {
    cursor: pointer;
    transition: transform 200ms var(--ease-out), border-color 200ms var(--ease-out),
                background-color 200ms var(--ease-out);
}
.ui-card--interactive:hover { transform: translateY(-2px); border-color: var(--border-strong); background: var(--surface-raised); }
.ui-card--interactive:active { transform: translateY(0) scale(0.995); }

/* ==========================================================================
   ПРИМИТИВ: ПУСТОЕ СОСТОЯНИЕ (.ui-empty)
   ========================================================================== */
.ui-empty {
    background: var(--surface);
    border: 1px dashed rgba(255, 255, 255, 0.12);
    border-radius: 14px; padding: 20px; text-align: center;
    color: var(--text-secondary); font-size: 13px; line-height: 1.5;
}
.ui-empty--hero { padding: 40px 24px; }
.ui-empty--hero .ui-empty__icon { font-size: 30px; margin-bottom: 10px; }
.ui-empty--hero b { display: block; font-size: 16px; color: var(--text-primary); margin-bottom: 6px; }
.ui-empty--hero p { max-width: 440px; margin: 0 auto 18px; }
/* Строчный вариант - когда «пусто» это подпись внутри блока, а не сам блок. */
.ui-empty--inline { background: none; border: none; padding: 6px 0; text-align: left; font-size: 12.5px; }

'''
assert s.count(anchor)==1
s=s.replace(anchor, prims+anchor)
io.open(p,'w',encoding='utf-8').write(s)
print('примитивы добавлены')
