# Мёртвые правила бейджей и пустых состояний.
dead = [
".kanban-count { background: rgba(255,255,255,0.1); padding: 2px 8px; border-radius: 10px; font-size: 12px; }\n",
".funnel-badge { font-size: 10px; font-weight: 700; padding: 3px 6px; border-radius: 5px; text-transform: uppercase; margin-right: 4px; }\n",
".limit-badge { font-size: 11px; font-weight: 600; padding: 4px 8px; border-radius: 6px; border: 1px solid var(--accent-green); color: var(--accent-green); display: inline-block; margin-bottom: 12px; }\n",
".card-badge { font-size: 11px; font-weight: 600; padding: 4px 10px; border-radius: 8px; text-transform: uppercase; }\n",
".format-tag { font-size: 11px; padding: 3px 8px; border-radius: 6px; font-weight: 600; background: rgba(255,255,255,0.08); color: var(--accent-orange); }\n",
""".cc-pill { display: inline-flex; align-items: center; font-size: 11px; font-weight: 600; padding: 3px 9px; border-radius: 7px; background: rgba(255,255,255,0.07); color: var(--text-secondary); }
.cc-pill-work { background: rgba(255,159,10,0.15); color: var(--accent-orange); }
.cc-pill-ready { background: rgba(10,132,255,0.15); color: var(--accent-blue); }
.cc-pill-done { background: rgba(48,209,88,0.15); color: var(--accent-green); }
.cc-pill-agent { background: rgba(191,90,242,0.15); color: var(--accent-purple); }
""",
""".cc-placeholder { background: var(--bg-grouped); border: 1px dashed rgba(255,255,255,0.12); border-radius: 14px; padding: 20px; text-align: center; color: var(--text-secondary); font-size: 13px; line-height: 1.5; }
.cc-placeholder-hero { padding: 40px 24px; }
.cc-placeholder-hero .cc-placeholder-icon { font-size: 30px; margin-bottom: 10px; }
.cc-placeholder-hero b { display: block; font-size: 16px; color: var(--text-primary); margin-bottom: 6px; }
.cc-placeholder-hero p { max-width: 440px; margin: 0 auto 18px; }
.cc-empty { font-size: 12.5px; color: var(--text-secondary); }
.cc-empty-inline { padding: 6px 0; }
""",
]
for d in dead:
    assert s.count(d)==1, d[:55]
    s=s.replace(d,'')
io.open(p,'w',encoding='utf-8').write(s)
print('дубли материала убраны')
